                        try (FileOutputStream fout = new FileOutputStream(content)) {
                            fout.write(fatt.getData());
                        }
                    }

                    return content;
                }
            }
        }

        return null;
    }

    public File getTempFile(FileAttachment fatt)
    {
        if( !tmp_dir.isDirectory() && !tmp_dir.mkdirs() )
